    inv_footer_note_html: "প্রতিটি রপ্তানিকৃত আইটেমে এর স্থায়ী লিংক + আপনি যেদিন পিন করেছেন তার তারিখ থাকে — গঠনগতভাবেই উদ্ধৃতি-মানের। শেয়ার করা একটি শুধু-পঠনযোগ্য স্ন্যাপশট আপলোড করে (৯০ দিনের লিংক); এই ব্রাউজার থেকে আর কিছুই বের হয় না।",
