    about_label_email: "ইমেইল",
    about_label_email_opt: "— ঐচ্ছিক, শুধু যদি আপনি উত্তর চান",
    about_btn_send: "মতামত পাঠান →",
    about_note_feedback_html: "আপনি যদি আপনার ইমেইল যোগ করেন, আমরা শুধু উত্তর দিতে এটি ব্যবহার করি। প্রতিটি জমাদান কিছু মৌলিক তথ্যও সংরক্ষণ করে — আপনার আইপি ঠিকানা এবং ব্রাউজার। স্প্যাম বন্ধ করতে আমরা এই তথ্য অল্প সময়ের জন্য রাখি। দেখুন <a href=\"#privacy\">গোপনীয়তা</a>।",
    about_err_short: "আরেকটু বিস্তারিত যোগ করুন — অন্তত একটি বাক্য।",
    about_err_long: "এটি একটু বেশি লম্বা — অনুগ্রহ করে ২,০০০ অক্ষরের নিচে রাখুন।",
    about_err_bademail: "সেই ইমেইল ঠিকানাটি ঠিক মনে হচ্ছে না — উত্তর না চাইলে এটি খালি রাখুন।",
    about_sending: "পাঠানো হচ্ছে…",
    about_thanks_html: "<b>ধন্যবাদ — আমরা পেয়েছি।</b>",
    about_thanks_reply: " যোগ করার মতো কিছু থাকলে আমরা উত্তর দেব।",
    about_reason_ratelimited: "অনেক বেশি বার্তা — একটু অপেক্ষা করুন।",
    about_reason_badmessage: "বার্তাটি খালি, খুব সংক্ষিপ্ত, বা খুব দীর্ঘ ছিল।",
    about_reason_badcategory: "একটি বিভাগ বেছে নিন — ত্রুটি, বৈশিষ্ট্যের ধারণা, বা সাধারণ।",
    about_reason_notconfigured: "মতামত এখনও চালু করা হয়নি।",
