    about_foot_html: "CityScroll · <a href=\"https://a856-cityrecord.nyc.gov/\" target=\"_blank\" rel=\"noopener noreferrer\">The City Record<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a>-এর উপর একটি অনুসন্ধান ইন্টারফেস · <a href=\"stats.html\">পরিসংখ্যান</a> · <a href=\"mailto:feedback%40cityscroll.org\">মতামত</a> · <a href=\"index.html\">হোম</a>",
    about_h_privacy: "গোপনীয়তা",
    about_p_privacy_intro: "CityScroll-এ কোনো পাসওয়ার্ড অ্যাকাউন্ট নেই এবং কোনো বিজ্ঞাপন প্রযুক্তি নেই। এটি আপনাকে অন্য সাইটে ট্র্যাক করে না।",
    about_li_privacy_html: "<li><b>অনুসন্ধান ও ফিল্টার</b> NYC Open Data ব্যবহার করে।</li><li><b>\"জিজ্ঞাসা করুন\" বাক্সটি</b> আপনাকে সহজ ইংরেজিতে অনুসন্ধান করতে দেয়। এটি আপনার লেখা আমাদের ওয়ার্কারে পাঠায়। ওয়ার্কার তারপর এটি Anthropic-এর Claude-এ পাঠায়, যা আপনার শব্দগুলিকে ফিল্টারে রূপান্তরিত করে। আমরা আপনার লেখা সংরক্ষণ করি না।</li><li><b>সাবস্ক্রাইব করা বা মতামত পাঠানো</b> আপনি আমাদের যা পাঠান তা সংরক্ষণ করে। এর মধ্যে আপনার সতর্কতা বা বার্তা এবং আপনার ইমেইল, যদি আপনি একটি শেয়ার করেন, অন্তর্ভুক্ত। আমরা আপনার অনুরোধ সম্পর্কে কিছু মৌলিক তথ্যও রাখি, যেমন আপনার আইপি ঠিকানা এবং ব্রাউজার। স্প্যাম ও অপব্যবহার বন্ধ করতে আমরা এটি অল্প সময়ের জন্য রাখি। প্রতিটি সতর্কতা ইমেইলে এক-ক্লিকে সাবস্ক্রিপশন বাতিলের লিংক থাকে।</li><li><b>ইমেইল লিংক, পিন ও সতর্কতা</b> — আপনার সতর্কতা ইমেইলের লিংকে ক্লিক করলে সেই ডিভাইসে আপনি সাইন ইন হন। ব্যানারে সাইন-ইন করা ইমেইল দেখানো হয় এবং তার সতর্কতা পরিচালনা, পিন করা আইটেম সিঙ্ক বা সাইন আউট করা যায় (\"আপনি নন?\")। সাইন ইন থাকা অবস্থায় সতর্কতা পরিচালনার জন্য দ্বিতীয় ইমেইল লিংক লাগে না।</li><li><b>পৃষ্ঠা দর্শন</b> Cloudflare Web Analytics দিয়ে ট্র্যাক করা হয়। এটি কোনো কুকি ব্যবহার করে না এবং শুধু সমষ্টি দেখায়। এটি দর্শন গণনা করে। এটি জানে না আপনি কে বা আপনাকে অন্য সাইটে অনুসরণ করে না।</li><li><b>ক্লিক ও স্ক্রল মানচিত্র</b> (Microsoft Clarity, চালু থাকলে) দেখায় মানুষ কোথায় ট্যাপ বা স্ক্রল করে, যাতে আমরা কঠিন অংশ ঠিক করতে পারি। টাইপ করা লেখা ও ফর্ম ক্ষেত্র — ইমেইলসহ — মাস্ক করা হয় এবং সাধারণ লেখা হিসেবে কখনো পাঠানো হয় না। আপনার ব্রাউজার Do Not Track বা Global Privacy Control সংকেত দিলে Clarity লোড হয় না। এটি বিজ্ঞাপন বা ব্যক্তিগত প্রোফাইলের জন্য ব্যবহৃত হয় না।</li>",
    session_signed_in: "{email} হিসাবে সাইন ইন করা হয়েছে — পিনগুলি এই ডিভাইসে আপনার সাথে থাকে।",
    session_manage_watches: "সতর্কতা পরিচালনা করুন",
    session_not_you: "আপনি নন?",
    session_dismiss: "বন্ধ",
    data_p_lede_html: "নগর নথির উপাত্তসেট, এক নজরে। আপনার ব্রাউজার <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a> থেকে লাইভ মোট টেনে আনে। সার্ভারে কিছুই সংরক্ষিত হয় না। সংখ্যাগুলি <a href=\"about.html#data\">সততার নিয়ম</a> অনুসরণ করে। পরিসংখ্যান তাদের নিজস্ব বিভাগের মধ্যেই থাকে। সম্ভাব্য উপাত্ত-প্রবেশের ভুল বাদ দেওয়া হয়েছে — $১০ বিলিয়ন বা তার বেশি পরিমাণ। স্থানধারক শেষ তারিখ প্রকৃত হিসেবে গণনা করা হয় না।",
    data_h_sections_html: "নথি আসলে কী দেখায় <span class=\"note\">(সব সময়, বিভাগ অনুযায়ী)</span>",
    data_note_sections_body: "নগর নথির বেশিরভাগই সিভিল-সার্ভিস চাকরি সম্পর্কিত কাগজপত্র। যেসব নোটিশ জনসাধারণের কাছে গুরুত্বপূর্ণ তা এর একটি ছোট অংশ মাত্র। তাই এই সাইটের প্রতিটি সংখ্যা প্রতি বিভাগ অনুযায়ী দেখানো হয়।",
    data_h_volume_html: "কতগুলি প্রকাশিত হয়েছে <span class=\"note\">(গত ১২ মাস)</span>",
    data_h_procmix_html: "ক্রয় সংমিশ্রণ <span class=\"note\">(গত ১২ মাস, নোটিশের ধরন অনুযায়ী)</span>",
    data_h_agencies_html: "প্রদত্ত অর্থ অনুযায়ী শীর্ষ সংস্থা <span class=\"note\">(গত ১২ মাস, পরিষ্কার করা)</span>",
    data_note_agencies_html: "\"পরিষ্কার করা\" মানে আমরা $১০ বিলিয়নের বেশি পরিমাণ বাদ দিয়েছি। আমরা মনে করি এগুলি উপাত্ত-প্রবেশের ভুল। দেখুন <a href=\"about.html#data\">অন্তর্নিহিত উপাত্ত</a>।",
    data_h_vendors_html: "প্রদত্ত অর্থ অনুযায়ী শীর্ষ বিক্রেতা <span class=\"note\">(গত ১২ মাস, পরিষ্কার করা)</span>",
