    api_p_intro_html: "CityScroll-এর প্রতিটি দৃশ্যের একটি যন্ত্র-পাঠযোগ্য প্রতিরূপ আছে। কোনো কী নেই, কোনো অ্যাকাউন্ট নেই; এন্ডপয়েন্টগুলি হার-সীমিত ও ক্যাশড, এবং কোনোটিই কোনো পেইড পরিষেবা স্পর্শ করে না। বেস URL: <code>https://api.cityscroll.org</code>।",
