    api_p_feeds_html: "<code>GET /feed.xml</code> (Atom) · <code>GET /feed.json</code> (JSON Feed 1.1) · <code>GET /feed.ics</code> (সাবস্ক্রাইবযোগ্য ক্যালেন্ডার — তারিখযুক্ত প্রতিটি নোটিশের জন্য একটি অনুষ্ঠান)। ১৫ মিনিট এজ-ক্যাশড।",
