    footer_standards: "মান",
    standards_title: "মান · CityScroll",
    std_h1: "আমরা যেসব মান অনুসরণ করি",
    std_p_lede_html: "এই পাতাটি নিউ ইয়র্ক সিটি ও নিউ ইয়র্ক স্টেট প্রকাশিত মানদণ্ডের সঙ্গে CityScroll-কে তুলনা করে। একটি অংশ ভাষা নিয়ে, অন্যটি প্রবেশযোগ্যতা (অ্যাক্সেসিবিলিটি) নিয়ে। আমরা প্রকৃতপক্ষে যা করি তা কেবল একটি সাধারণ পর্যবেক্ষণ হিসেবে বলা হয়েছে, কখনোই সনদায়ন (সার্টিফিকেশন) হিসেবে নয়।",
    std_h_languages: "ভাষা প্রবেশাধিকার, পাশাপাশি",
    std_p_languages_html: "নিউ ইয়র্ক সিটির <a href=\"https://citymeetings.nyc/meetings/new-york-city-council/2024-09-24-0100-pm-committee-on-immigration/chapter/explanation-of-local-law-30-of-2017-and-its-requirements/\" target=\"_blank\" rel=\"noopener noreferrer\">২০১৭ সালের স্থানীয় আইন ৩০<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a>-এ ইংরেজি ছাড়াও শহরজুড়ে দশটি ভাষা উল্লেখ করা হয়েছে, যা শহরের সংস্থাগুলোকে অবশ্যই দিতে হবে। নিচের সারণিটি সেই তালিকাকে CityScroll-এর নিজস্ব ভাষা পরিবর্তকের সঙ্গে লাইভভাবে তুলনা করে: পরিবর্তকে কোনো ভাষা যোগ বা বাদ দেওয়া হলে, এই সারণিও তার সঙ্গে বদলে যায়।",
    std_table_caption: "স্থানীয় আইন ৩০-এর দশটি ভাষা CityScroll-এর ভাষা পরিবর্তকের সঙ্গে তুলনা",
