    std_h_accessibility: "প্রবেশযোগ্যতার লক্ষ্য, এবং তা কোন দিকে যাচ্ছে",
    std_a11y_today_label: "আজ",
    std_a11y_today_html: "নিউ ইয়র্ক সিটির নিজস্ব <a href=\"https://rules.cityofnewyork.us/nyc-rules-website-accessibility-statement/\" target=\"_blank\" rel=\"noopener noreferrer\">ওয়েবসাইট প্রবেশযোগ্যতা বিবৃতি<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a> <b>WCAG 2.1 লেভেল AA</b> লক্ষ্য করে এবং শহরের সাইটগুলোকে \"আংশিকভাবে সঙ্গতিপূর্ণ\" বলে বর্ণনা করে।",
    std_a11y_next_label: "জানুয়ারি ২০২৭",
    std_a11y_next_html: "নিউ ইয়র্ক স্টেটের প্রযুক্তি আইন (<a href=\"https://designsystem.ny.gov/foundations/accessibility/\" target=\"_blank\" rel=\"noopener noreferrer\">STL §103-d<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a>) অনুযায়ী রাজ্য সংস্থার ওয়েবসাইটগুলোকে <b>WCAG 2.2 লেভেল AA</b>-তে উন্নীত হতে হবে। এটি রাজ্য সংস্থাগুলোর জন্য প্রযোজ্য, সরাসরি নিউ ইয়র্ক সিটির জন্য নয় — তবে মানদণ্ড কোন দিকে যাচ্ছে তার সবচেয়ে স্পষ্ট প্রকাশিত সংকেত এটি।",
    std_h_self_conformance: "প্রবেশযোগ্যতা নিয়ে CityScroll-এর নিজস্ব অবস্থান",
    std_p_self_conformance_lede: "এগুলো লক্ষ্য ও ধারাবাহিক পর্যবেক্ষণ, সনদায়ন নয়।",
    std_self_target_label: "CityScroll-এর লক্ষ্য",
    std_self_target_html: "CityScroll আজ <b>WCAG 2.2 লেভেল AA</b> লক্ষ্য করে।",
    std_self_observations_label: "ধারাবাহিক পর্যবেক্ষণ",
    std_li_axe_pr: "axe প্রবেশযোগ্যতা যাচাই প্রতিটি পরিবর্তনের অনুরোধে প্রতিটি প্রকাশ্য পাতা ও সক্রিয় ট্যাব অবস্থায় চলে। নতুন কোনো গুরুতর বা মারাত্মক লঙ্ঘন বিল্ড ব্যর্থ করে।",
    std_li_ll30_live: "উপরের স্থানীয় আইন ৩০-এর সারণি সাইটের বর্তমান ভাষা পরিবর্তকটি সরাসরি পড়ে। পরিবর্তকে কোনো ভাষা যোগ বা বাদ দিলে সারণিটিও বদলে যায়।",
    std_li_reading_ratchet: "পাঠযোগ্যতার স্তরের যাচাই প্রতিটি পরিবর্তনের অনুরোধে প্রকাশ্য পাতাগুলোতে চলে। কোনো পাতা তার সংরক্ষিত ভিত্তির চেয়ে পড়তে কঠিন হলে যাচাই ব্যর্থ হয়।",
    std_h_posture: "আমরা প্রকৃতপক্ষে যা তৈরি করেছি (এই পাতায় যাচাই করা)",
    std_p_posture_lede: "এর কোনোটিই সনদায়ন নয়। কিছু লাইন এই পাতার নিজস্ব মার্কআপের বিপরীতে লাইভভাবে যাচাই করা হয়। বাকিগুলো সাইটটি কীভাবে কাজ করে তার সাধারণ তথ্য। নিজে যাচাই করতে যেকোনো সময় সোর্স দেখুন।",
    std_li_no_login: "কোনো বিজ্ঞপ্তি খুঁজতে বা পড়তে অ্যাকাউন্ট, লগইন বা পাসওয়ার্ড দরকার নেই।",
    std_li_no_browser_gate: "কোনো ব্রাউজার-সংস্করণ যাচাই প্রবেশ আটকায় না। পাতাটি লোড হওয়ার আগে আপনি কোন ব্রাউজার ব্যবহার করছেন তা পরীক্ষা করে না।",
