    exam_list_duration_context: "রাজ্য আইন অনুযায়ী যোগ্য তালিকা সাধারণত এক থেকে চার বছর স্থায়ী হয়। এটি আইনি প্রেক্ষাপট, পূর্বাভাস নয়।",
    exam_list_law_source: "নিউ ইয়র্ক সিভিল সার্ভিস আইন §56",
    about_staffing_formula_heading: "সিভিল সার্ভিস যোগ্য তালিকার সময়",
    about_staffing_formula_html: "আমরা DCAS বার্ষিক পরীক্ষার সূচির প্রতিটি পরীক্ষার নম্বরকে পরীক্ষা-স্তরের সিভিল সার্ভিস তালিকা সমষ্টির সঙ্গে হুবহু মিলাই। সময়কাল হলো <b>তালিকা প্রতিষ্ঠার তারিখ − আবেদনকাল বন্ধের তারিখ</b>। ওপেন-কম্পিটিটিভ ও পদোন্নতি গোষ্ঠীতে (ন্যূনতম ২০ পরীক্ষা) p10, মধ্যমা ও p90 অভিজ্ঞতামূলক বণ্টনের নিকটতম র‍্যাঙ্ক; ছোট গোষ্ঠী শহরব্যাপী বণ্টন ব্যবহার করে। সময়ভিত্তিক ব্যাকটেস্ট ২০২৪ পর্যন্ত প্রতিষ্ঠিত তালিকায় প্রশিক্ষণ নিয়ে ২০২৫–২০২৬ ফলাফল মূল্যায়ন করে। অন্তত ৫০টি সমাধান, ৭০%–৯০% p10–p90 কভারেজ এবং প্রযোজ্য ক্ষেত্রে একমুখী ঘটনা-কুইন্টাইল হলেই পরীক্ষা-নির্দিষ্ট তারিখ দেখানো হয়; নইলে শুধু গোষ্ঠীর মধ্যমা দেখানো হয়। ত্রুটির উৎসের মধ্যে সূচি সংশোধন, পুনর্ব্যবহৃত পরীক্ষা নম্বর, বিলম্বিত তালিকা এবং প্রতিষ্ঠার তারিখবিহীন রেকর্ড আছে। আবেদনকারীর সারি, নাম, স্কোর বা র‍্যাঙ্ক কখনো ব্যবহার করা হয় না।",
